public function __construct($years = null, $months = null, $weeks = null, $days = null, $hours = null, $minutes = null, $seconds = null, $microseconds = null)
{
    $this->originalInput = \func_num_args() === 1 ? $years : \func_get_args();

    if ($years instanceof Closure) {
        $this->step = $years;
        $years = null;
    }

    if ($years instanceof DateInterval) {
        $intervalSpec = static::getDateIntervalSpec($years);
        parent::__construct($intervalSpec);
        $this->f = $years->f;
        $this->invert = $years->invert;

        foreach (['y', 'm', 'd', 'h', 'i', 's'] as $intervalUnit) {
            if ($years->$intervalUnit < 0) {
                $this->$intervalUnit *= self::NEGATIVE;
            }
        }

        return;
    }

    $spec = $years;
    $isStringSpec = (\is_string($spec) && !preg_match('/^[\d.]/', $spec));

    if (!$isStringSpec || (float) $years) {
        $spec = static::PERIOD_PREFIX;
        $daysPerWeek = static::getDaysPerWeek();

        if ($years > 0) {
            $spec .= $years.static::PERIOD_YEARS;
        }

        if ($months > 0) {
            $spec .= $months.static::PERIOD_MONTHS;
        }

        $specDays = 0;
        if ($weeks > 0) {
            $specDays += $weeks * $daysPerWeek;
        }

        if ($days > 0) {
            $specDays += $days;
        }

        if ($specDays > 0) {
            $spec .= $specDays.static::PERIOD_DAYS;
        }

        if ($hours > 0 || $minutes > 0 || $seconds > 0) {
            $spec .= static::PERIOD_TIME_PREFIX;

            if ($hours > 0) {
                $spec .= $hours.static::PERIOD_HOURS;
            }

            if ($minutes > 0) {
                $spec .= $minutes.static::PERIOD_MINUTES;
            }

            if ($seconds > 0) {
                $spec .= $seconds.static::PERIOD_SECONDS;
            }
        }

        if ($spec === static::PERIOD_PREFIX) {
            $spec .= '0'.static::PERIOD_YEARS;
        }
    }

    try {
        parent::__construct($spec);
    } catch (Throwable $exception) {
        try {
            parent::__construct('PT0S');

            if ($isStringSpec) {
                if (!preg_match('/^P
                    (?:(?<year>[+-]?\d*(?:\.\d+)?)Y)?
                    (?:(?<month>[+-]?\d*(?:\.\d+)?)M)?
                    (?:(?<week>[+-]?\d*(?:\.\d+)?)W)?
                    (?:(?<day>[+-]?\d*(?:\.\d+)?)D)?
                    (?:T
                        (?:(?<hour>[+-]?\d*(?:\.\d+)?)H)?
                        (?:(?<minute>[+-]?\d*(?:\.\d+)?)M)?
                        (?:(?<second>[+-]?\d*(?:\.\d+)?)S)?
                    )?
                $/x', $spec, $match)) {
                    throw new InvalidArgumentException("Invalid duration: $spec");
                }

                $years = (float) ($match['year'] ?? 0);
                $this->assertSafeForInteger('year', $years);
                $months = (float) ($match['month'] ?? 0);
                $this->assertSafeForInteger('month', $months);
                $weeks = (float) ($match['week'] ?? 0);
                $this->assertSafeForInteger('week', $weeks);
                $days = (float) ($match['day'] ?? 0);
                $this->assertSafeForInteger('day', $days);
                $hours = (float) ($match['hour'] ?? 0);
                $this->assertSafeForInteger('hour', $hours);
                $minutes = (float) ($match['minute'] ?? 0);
                $this->assertSafeForInteger('minute', $minutes);
                $seconds = (float) ($match['second'] ?? 0);
                $this->assertSafeForInteger('second', $seconds);
            }

            $daysPerWeek = static::getDaysPerWeek();
            $totalDays = (($weeks * $daysPerWeek) + $days);
            if ($totalDays) {
                if (!\is_int($totalDays)) {
                    if ($totalDays >= 0x7fffffffffffffff) {
                        throw new OutOfRangeException('days total (including weeks)', -0x7fffffffffffffff, 0x7fffffffffffffff, $totalDays);
                    }

                    if ($totalDays <= -0x7fffffffffffffff) {
                        throw new OutOfRangeException('days total (including weeks)', -0x7fffffffffffffff, 0x7fffffffffffffff, $totalDays);
                    }
                }
            }

            $this->y = (int) $years;
            $this->m = (int) $months;
            $this->d = (int) $totalDays;
            $this->h = (int) $hours;
            $this->i = (int) $minutes;
            $this->s = (int) $seconds;

            if (
                ((float) $this->y) !== $years ||
                ((float) $this->m) !== $months ||
                ((float) $this->d) !== $totalDays ||
                ((float) $this->h) !== $hours ||
                ((float) $this->i) !== $minutes ||
                ((float) $this->s) !== $seconds
            ) {
                $this->add(static::fromString(
                    ($years - $this->y).' years '.
                    ($months - $this->m).' months '.
                    ($totalDays - $this->d).' days '.
                    ($hours - $this->h).' hours '.
                    ($minutes - $this->i).' minutes '.
                    ($seconds - $this->s).' seconds '
                ));
            }
        } catch (Throwable $secondException) {
            if ($secondException instanceof OutOfRangeException) {
                throw $secondException;
            }

            throw $exception;
        }
    }

    if ($microseconds !== null) {
        $this->f = $microseconds / Carbon::MICROSECONDS_PER_SECOND;
    }

    foreach (['years', 'months', 'weeks', 'days', 'hours', 'minutes', 'seconds'] as $unit) {
        $normalizedUnit = Unit::toNameIfUnit($unit);
        if ($$unit < 0) {
            $this->set(Carbon::singularUnit(rtrim((string) $normalizedUnit, 'z')), $$unit);
        }
    }
}

